import{_ as r,o as e,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Crash Telemetry - Observability in Action - Yaarit Hatuka, IBM","description":"","frontmatter":{"title":"Ceph Crash Telemetry - Observability in Action - Yaarit Hatuka, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Telemetry","Observability","Distributed Storage","Data Analysis"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Crash_Telemetry_-_Observability_in_Action_-_Yaarit_Hatuka_IBM.md","filePath":"posts/2023/Ceph_Crash_Telemetry_-_Observability_in_Action_-_Yaarit_Hatuka_IBM.md","lastUpdated":1780459816000}'),s={name:"posts/2023/Ceph_Crash_Telemetry_-_Observability_in_Action_-_Yaarit_Hatuka_IBM.md"};function o(n,t,a,g,p,_){return e(),l("div",null,[...t[0]||(t[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Ceph Crash Telemetry 项目概述与讨论</p><p><strong>会议时间：</strong> [具体日期]</p><p><strong>会议地点：</strong> [具体地点]</p><p><strong>主讲人：</strong> Yaarit（Telemetry 技术负责人，IBM）</p><p><strong>参会人员：</strong> [列出主要参会人员]</p><p><strong>会议内容总结：</strong></p><ol><li><p><strong>Telemetry 项目概述</strong></p><ul><li><strong>动机：</strong> 了解社区中 Ceph 集群的分布、版本、存储容量、驱动模型以及用户体验等问题。</li><li><strong>架构：</strong> Telemetry 模块允许集群匿名报告安装和配置数据，数据在后端聚合并通过公共仪表板（telemetry-public.sef.com）展示。</li><li><strong>功能：</strong> 自 Mimic 版本引入以来，已有约 2500 个集群参与，报告了近 1 Exabyte 的存储容量。</li></ul></li><li><p><strong>数据报告与隐私</strong></p><ul><li><strong>默认设置：</strong> Telemetry 报告默认关闭，用户需通过 CLI 命令或 Ceph 仪表板向导明确选择加入。</li><li><strong>隐私保护：</strong> 报告不包含敏感或识别信息，如用户名、主机名、对象名或内容。集群通过随机 UUID 标识，不报告 FSID，并剔除驱动序列 ID 和 IP 地址。</li></ul></li><li><p><strong>报告渠道与数据处理</strong></p><ul><li><strong>渠道：</strong> 包括基本信息、崩溃、设备、身份和性能渠道。基本和设备渠道默认开启，身份和性能渠道需用户明确选择。</li><li><strong>数据处理：</strong> 使用正则表达式处理和标准化崩溃报告，以便于识别和分类。</li></ul></li><li><p><strong>成功案例与用户反馈</strong></p><ul><li><strong>崩溃报告：</strong> 自动将崩溃报告同步到 Redmine 问题跟踪系统，帮助开发者识别和修复问题。</li><li><strong>用户参与：</strong> 用户可以通过 Telemetry 数据验证其安装，并贡献于开放数据集，帮助改进驱动健康指标和故障预测模型。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li><strong>增强用户可见性：</strong> 考虑在公共仪表板中为用户提供特定视图，显示其集群的崩溃状态和修复信息。</li><li><strong>改进数据收集：</strong> 继续添加新的数据收集项，并考虑用户的具体需求和反馈。</li><li><strong>提高项目可见性：</strong> 在 Redmine 跟踪器顶部添加 Telemetry 链接，提高项目在社区中的知名度。</li><li><strong>改进崩溃报告跟踪：</strong> 考虑为用户提供更详细的集群崩溃报告跟踪和反馈机制。</li><li><strong>扩展性能指标收集：</strong> 考虑收集更多性能指标，以便更好地了解集群性能并优化 Telemetry 数据集。</li></ul></li></ol><p><strong>会议结束：</strong> [具体时间]</p><p><strong>后续行动：</strong></p><ul><li>继续优化 Telemetry 数据收集和处理流程。</li><li>增强用户界面和报告功能，提高用户参与度。</li><li>在社区中推广 Telemetry 项目，收集更多用户反馈和建议。</li><li>探索新的数据收集项和性能指标，以改善 Telemetry 数据集。</li><li>改进崩溃报告的跟踪和反馈机制，提高问题解决效率。</li></ul><p><strong>备注：</strong></p><ul><li>会议中提到的具体命令和链接需在实际操作中验证其准确性和可用性。</li><li>对于新功能的添加和改进，将持续关注用户反馈并进行迭代优化。</li></ul><p><strong>会议记录人：</strong> [记录人姓名]</p><p><strong>审核：</strong> [审核人姓名]</p><p><strong>日期：</strong> [记录日期]</p>',16)])])}const y=r(s,[["render",o]]);export{u as __pageData,y as default};
